__all__ = ["Table", "Plain"]


class Table:
    def get(self, key, default=None):
        try:
            return self[key]
        except KeyError:
            return default

    def update(self, other):
        for k in other:
            self[k] = other[k]


class Plain:
    def get(self, key):
        return key


class _Hidden:
    def get(self, key):
        return self[key]
